#include <iostream>
#include <algorithm>
#include <string>
#include <queue>
#include <unordered_map>

using namespace std;

int bfs(string start) {
    string end = "12345678x";
    queue<string> q;
    unordered_map<string, int> dist;

    q.push(start);
    dist[start] = 0;

    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, -1, 1};

    while (!q.empty()) {
        string t = q.front();
        q.pop();

        if (t == end) return dist[t];

        // 获取 'x' 在一维字符串中的下标
        int k = t.find('x');
        int x = k / 3, y = k % 3;

        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            if (nx >= 0 && nx < 3 && ny >= 0 && ny < 3) {
                int next_k = nx * 3 + ny;
                string temp = t;
                swap(temp[k], temp[next_k]);

                if (dist.find(temp) == dist.end()) {
                    dist[temp] = dist[t] + 1;
                    q.push(temp);
                }
            }
        }
    }
    return -1;
}

int main() {
    string start = "";
    for (int i = 0; i < 9; ++i) {
        char c;
        cin >> c;
        start += c;
    }

    cout << bfs(start) << endl;
    return 0;
}
